class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self._options: list[str] = []
        self._counts: dict[str, int] = {}
        self._voters: set[str] = set()

    def add_option(self, option: str) -> None:
        self._options.append(option)
        if option not in self._counts:
            self._counts[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if voter in self._voters:
            raise ValueError("Voter has already voted")
        if option not in self._counts:
            raise ValueError("Option does not exist")

        self._voters.add(voter)
        self._counts[option] += 1

    def winner(self) -> str | None:
        if len(self._voters) < 3:
            return None
        return max(reversed(self._options), key=self._counts.__getitem__)
